CREATE TABLE IF NOT EXISTS schema_migrations (version BIGINT PRIMARY KEY, name TEXT NOT NULL, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
-- create "admin_audit_logs" table
CREATE TABLE "admin_audit_logs" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "actor" text NOT NULL,
  "action" text NOT NULL,
  "resource" text NOT NULL,
  "before" jsonb NULL,
  "after" jsonb NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id")
);
-- create "agent_outbound_messages" table
CREATE TABLE "agent_outbound_messages" (
  "id" uuid NOT NULL,
  "run_id" text NOT NULL DEFAULT '',
  "sequence" integer NOT NULL,
  "tool_call_id" text NULL,
  "text_content" text NOT NULL,
  "status" text NOT NULL,
  "platform_message_id" bigint NULL,
  "error_code" text NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "claim_token" uuid NOT NULL DEFAULT gen_random_uuid(),
  "bot_id" bigint NOT NULL,
  "conversation_id" uuid NOT NULL,
  "job_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "agent_outbound_messages_sequence_check" CHECK (sequence > 0),
  CONSTRAINT "agent_outbound_messages_status_check" CHECK (status = ANY (ARRAY['prepared'::text, 'sending'::text, 'sent'::text, 'failed'::text, 'unknown'::text, 'denied'::text, 'cancelled'::text]))
);
-- create index "agent_outbound_conversation_timeline" to table: "agent_outbound_messages"
CREATE INDEX "agent_outbound_conversation_timeline" ON "agent_outbound_messages" ("conversation_id", "created_at", "sequence");
-- create index "agent_outbound_job_tool_call_uidx" to table: "agent_outbound_messages"
CREATE UNIQUE INDEX "agent_outbound_job_tool_call_uidx" ON "agent_outbound_messages" ("job_id", "tool_call_id") WHERE (tool_call_id IS NOT NULL);
-- create index "agent_outbound_messages_job_id_sequence_key" to table: "agent_outbound_messages"
CREATE UNIQUE INDEX "agent_outbound_messages_job_id_sequence_key" ON "agent_outbound_messages" ("job_id", "sequence");
-- create "agent_run_budgets" table
CREATE TABLE "agent_run_budgets" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "reserved_messages" integer NOT NULL DEFAULT 0,
  "reserved_chars" integer NOT NULL DEFAULT 0,
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "job_id" bigint NOT NULL,
  PRIMARY KEY ("id")
);
-- create index "agent_run_budgets_job_key" to table: "agent_run_budgets"
CREATE UNIQUE INDEX "agent_run_budgets_job_key" ON "agent_run_budgets" ("job_id");
-- create "agent_sending_policies" table
CREATE TABLE "agent_sending_policies" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "bot_id" bigint NOT NULL,
  "scope_type" text NOT NULL,
  "scope_id" bigint NOT NULL,
  "max_messages_per_run" integer NOT NULL DEFAULT 3,
  "max_chars_per_message" integer NOT NULL DEFAULT 500,
  "max_total_chars_per_run" integer NOT NULL DEFAULT 1500,
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "min_interval_ms" integer NOT NULL DEFAULT 700,
  PRIMARY KEY ("id"),
  CONSTRAINT "agent_sending_policies_check" CHECK (max_chars_per_message <= max_total_chars_per_run),
  CONSTRAINT "agent_sending_policies_max_chars_per_message_check" CHECK (max_chars_per_message > 0),
  CONSTRAINT "agent_sending_policies_max_messages_per_run_check" CHECK (max_messages_per_run > 0),
  CONSTRAINT "agent_sending_policies_max_total_chars_per_run_check" CHECK (max_total_chars_per_run > 0),
  CONSTRAINT "agent_sending_policies_min_interval_ms_check" CHECK (min_interval_ms >= 0),
  CONSTRAINT "agent_sending_policies_scope_type_check" CHECK (scope_type = ANY (ARRAY['group'::text, 'private'::text]))
);
-- create index "agent_sending_policies_business_key" to table: "agent_sending_policies"
CREATE UNIQUE INDEX "agent_sending_policies_business_key" ON "agent_sending_policies" ("bot_id", "scope_type", "scope_id");
-- create "bot_accounts" table
CREATE TABLE "bot_accounts" (
  "bot_id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "nickname" text NOT NULL DEFAULT '',
  "last_seen_at" timestamptz NULL,
  PRIMARY KEY ("bot_id")
);
-- create "contacts" table
CREATE TABLE "contacts" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "user_id" bigint NOT NULL,
  "nickname" text NOT NULL DEFAULT '',
  "remark" text NOT NULL DEFAULT '',
  "last_seen_at" timestamptz NULL,
  "bot_id" bigint NOT NULL,
  PRIMARY KEY ("id")
);
-- create index "contacts_business_key" to table: "contacts"
CREATE UNIQUE INDEX "contacts_business_key" ON "contacts" ("bot_id", "user_id");
-- create "conversations" table
CREATE TABLE "conversations" (
  "id" uuid NOT NULL,
  "kind" text NOT NULL,
  "target_id" bigint NOT NULL,
  "last_message_at" timestamptz NULL,
  "bot_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "conversations_kind_check" CHECK (kind = ANY (ARRAY['group'::text, 'private'::text]))
);
-- create index "conversations_bot_id_kind_target_id_key" to table: "conversations"
CREATE UNIQUE INDEX "conversations_bot_id_kind_target_id_key" ON "conversations" ("bot_id", "kind", "target_id");
-- create "group_members" table
CREATE TABLE "group_members" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "group_id" bigint NOT NULL,
  "user_id" bigint NOT NULL,
  "nickname" text NOT NULL DEFAULT '',
  "card" text NOT NULL DEFAULT '',
  "role" text NOT NULL DEFAULT 'member',
  "last_seen_at" timestamptz NULL,
  "bot_id" bigint NOT NULL,
  PRIMARY KEY ("id")
);
-- create index "group_members_business_key" to table: "group_members"
CREATE UNIQUE INDEX "group_members_business_key" ON "group_members" ("bot_id", "group_id", "user_id");
-- create "intent_decision_steps" table
CREATE TABLE "intent_decision_steps" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "step_index" integer NOT NULL,
  "phase" text NOT NULL,
  "reason_code" text NOT NULL DEFAULT '',
  "detail" jsonb NOT NULL DEFAULT '{}',
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "decision_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "intent_decision_steps_step_index_check" CHECK (step_index >= 0)
);
-- create index "intent_decision_steps_decision" to table: "intent_decision_steps"
CREATE INDEX "intent_decision_steps_decision" ON "intent_decision_steps" ("decision_id", "step_index");
-- create index "intent_decision_steps_decision_id_step_index_key" to table: "intent_decision_steps"
CREATE UNIQUE INDEX "intent_decision_steps_decision_id_step_index_key" ON "intent_decision_steps" ("decision_id", "step_index");
-- create "intent_decisions" table
CREATE TABLE "intent_decisions" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "provider" text NOT NULL,
  "model" text NOT NULL DEFAULT '',
  "decision" text NOT NULL,
  "reason_code" text NOT NULL,
  "scores" jsonb NOT NULL DEFAULT '{}',
  "latency_ms" integer NOT NULL DEFAULT 0,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "ruleset_version" text NOT NULL DEFAULT '',
  "job_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "intent_decisions_decision_check" CHECK (decision = ANY (ARRAY['reply'::text, 'silent'::text, 'defer'::text]))
);
-- create index "intent_decisions_job" to table: "intent_decisions"
CREATE INDEX "intent_decisions_job" ON "intent_decisions" ("job_id");
-- create "intent_rule_activations" table
CREATE TABLE "intent_rule_activations" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "bot_id" bigint NOT NULL,
  "scope_type" text NOT NULL,
  "scope_id" bigint NOT NULL,
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "ruleset_id" bigint NOT NULL,
  PRIMARY KEY ("id")
);
-- create index "intent_rule_activations_business_key" to table: "intent_rule_activations"
CREATE UNIQUE INDEX "intent_rule_activations_business_key" ON "intent_rule_activations" ("bot_id", "scope_type", "scope_id");
-- create "intent_rule_entries" table
CREATE TABLE "intent_rule_entries" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "priority" integer NOT NULL,
  "match" jsonb NOT NULL DEFAULT '{}',
  "action" jsonb NOT NULL,
  "enabled" boolean NOT NULL DEFAULT true,
  "ruleset_id" bigint NOT NULL,
  PRIMARY KEY ("id")
);
-- create index "intent_rule_entries_ruleset_id_priority_key" to table: "intent_rule_entries"
CREATE UNIQUE INDEX "intent_rule_entries_ruleset_id_priority_key" ON "intent_rule_entries" ("ruleset_id", "priority");
-- create "intent_rulesets" table
CREATE TABLE "intent_rulesets" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "bot_id" bigint NOT NULL,
  "scope_type" text NOT NULL,
  "scope_id" bigint NOT NULL,
  "version" integer NOT NULL,
  "status" text NOT NULL,
  "note" text NOT NULL DEFAULT '',
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "published_at" timestamptz NULL,
  "builtin_rules" jsonb NOT NULL DEFAULT '{}',
  "targets" jsonb NOT NULL DEFAULT '[]',
  "deleted_at" timestamptz NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "intent_rulesets_scope_type_check" CHECK (scope_type = ANY (ARRAY['group'::text, 'private'::text])),
  CONSTRAINT "intent_rulesets_status_check" CHECK (status = ANY (ARRAY['draft'::text, 'published'::text, 'archived'::text])),
  CONSTRAINT "intent_rulesets_version_check" CHECK (version > 0)
);
-- create index "intent_rulesets_bot_id_scope_type_scope_id_version_key" to table: "intent_rulesets"
CREATE UNIQUE INDEX "intent_rulesets_bot_id_scope_type_scope_id_version_key" ON "intent_rulesets" ("bot_id", "scope_type", "scope_id", "version");
-- create index "intent_rulesets_scope" to table: "intent_rulesets"
CREATE INDEX "intent_rulesets_scope" ON "intent_rulesets" ("bot_id", "scope_type", "scope_id", "version");
-- create "memories" table
CREATE TABLE "memories" (
  "memory_id" uuid NOT NULL,
  "visibility" text NOT NULL,
  "owner_key" text NOT NULL DEFAULT '',
  "content" text NOT NULL,
  "source" text NOT NULL DEFAULT '',
  "confidence" real NOT NULL DEFAULT 0,
  "status" text NOT NULL DEFAULT 'candidate',
  "approved_by" text NOT NULL DEFAULT '',
  "expires_at" timestamptz NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "bot_id" bigint NOT NULL,
  "source_message_id" bigint NULL,
  PRIMARY KEY ("memory_id"),
  CONSTRAINT "memories_status_check" CHECK (status = ANY (ARRAY['candidate'::text, 'active'::text, 'superseded'::text, 'deleted'::text])),
  CONSTRAINT "memories_visibility_check" CHECK (visibility = ANY (ARRAY['bot_shared'::text, 'group'::text, 'private_user'::text, 'conversation'::text]))
);
-- create index "memories_visibility" to table: "memories"
CREATE INDEX "memories_visibility" ON "memories" ("bot_id", "visibility", "owner_key", "status");
-- create "message_jobs" table
CREATE TABLE "message_jobs" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "status" text NOT NULL DEFAULT 'pending',
  "attempts" integer NOT NULL DEFAULT 0,
  "next_run_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "last_error_code" text NULL,
  "traceparent" text NOT NULL DEFAULT '',
  "tracestate" text NOT NULL DEFAULT '',
  "delivery_outcome" text NOT NULL DEFAULT '',
  "delivery_reason" text NOT NULL DEFAULT '',
  "denied_count" integer NOT NULL DEFAULT 0,
  "claim_token" uuid NULL,
  "lease_expires_at" timestamptz NULL,
  "incoming_message_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "message_jobs_denied_count_check" CHECK (denied_count >= 0),
  CONSTRAINT "message_jobs_lease_check" CHECK (((status = 'processing'::text) AND (claim_token IS NOT NULL) AND (lease_expires_at IS NOT NULL)) OR ((status <> 'processing'::text) AND (claim_token IS NULL) AND (lease_expires_at IS NULL))),
  CONSTRAINT "message_jobs_status_check" CHECK (status = ANY (ARRAY['pending'::text, 'processing'::text, 'done'::text, 'failed'::text, 'cancelled'::text]))
);
-- create index "message_jobs_expired" to table: "message_jobs"
CREATE INDEX "message_jobs_expired" ON "message_jobs" ("lease_expires_at") WHERE (status = 'processing'::text);
-- create index "message_jobs_incoming_message_id_key" to table: "message_jobs"
CREATE UNIQUE INDEX "message_jobs_incoming_message_id_key" ON "message_jobs" ("incoming_message_id");
-- create index "message_jobs_ready" to table: "message_jobs"
CREATE INDEX "message_jobs_ready" ON "message_jobs" ("status", "next_run_at", "id");
-- create "messages" table
CREATE TABLE "messages" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "direction" text NOT NULL,
  "platform_message_id" bigint NULL,
  "sender_id" bigint NOT NULL,
  "text_content" text NOT NULL DEFAULT '',
  "segments" jsonb NOT NULL DEFAULT '[]',
  "sent_status" text NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "outbound_id" uuid NULL,
  "bot_id" bigint NOT NULL,
  "conversation_id" uuid NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "messages_direction_check" CHECK (direction = ANY (ARRAY['incoming'::text, 'outgoing'::text])),
  CONSTRAINT "messages_sent_status_check" CHECK ((sent_status IS NULL) OR (sent_status = ANY (ARRAY['sent'::text, 'failed'::text, 'unknown'::text])))
);
-- create index "messages_conversation_timeline" to table: "messages"
CREATE INDEX "messages_conversation_timeline" ON "messages" ("conversation_id", "created_at", "id");
-- create index "messages_created_at" to table: "messages"
CREATE INDEX "messages_created_at" ON "messages" ("created_at");
-- create index "messages_incoming_event_uniq" to table: "messages"
CREATE UNIQUE INDEX "messages_incoming_event_uniq" ON "messages" ("bot_id", "conversation_id", "platform_message_id") WHERE ((direction = 'incoming'::text) AND (platform_message_id IS NOT NULL));
-- create index "messages_outbound_unique" to table: "messages"
CREATE UNIQUE INDEX "messages_outbound_unique" ON "messages" ("outbound_id") WHERE (outbound_id IS NOT NULL);
-- create "qq_groups" table
CREATE TABLE "qq_groups" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "group_id" bigint NOT NULL,
  "name" text NOT NULL DEFAULT '',
  "member_count" integer NOT NULL DEFAULT 0,
  "last_seen_at" timestamptz NULL,
  "bot_id" bigint NOT NULL,
  PRIMARY KEY ("id")
);
-- create index "qq_groups_business_key" to table: "qq_groups"
CREATE UNIQUE INDEX "qq_groups_business_key" ON "qq_groups" ("bot_id", "group_id");
-- create "scope_policies" table
CREATE TABLE "scope_policies" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "scope_type" text NOT NULL,
  "scope_id" bigint NOT NULL,
  "enabled" boolean NOT NULL DEFAULT false,
  "reply_mode" text NOT NULL DEFAULT 'mention_only',
  "store_messages" boolean NOT NULL DEFAULT true,
  "allow_memory_write" boolean NOT NULL DEFAULT false,
  "allow_history_read" boolean NOT NULL DEFAULT false,
  "min_reply_interval_ms" integer NOT NULL DEFAULT 10000,
  "max_replies_per_hour" integer NOT NULL DEFAULT 0,
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "tool_permissions" jsonb NOT NULL DEFAULT '{}',
  "version" bigint NOT NULL DEFAULT 1,
  "previous_reply_permission" jsonb NULL,
  "max_messages_per_run" integer NOT NULL DEFAULT 0,
  "max_chars_per_message" integer NOT NULL DEFAULT 4500,
  "max_total_chars_per_run" integer NOT NULL DEFAULT 0,
  "message_interval_ms" integer NOT NULL DEFAULT 700,
  "bot_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "scope_policies_message_interval_ms_check" CHECK ((message_interval_ms >= 0) AND (message_interval_ms <= 60000)),
  CONSTRAINT "scope_policies_reply_mode_check" CHECK (reply_mode = ANY (ARRAY['mention_only'::text, 'intent_based'::text, 'always_reply'::text, 'observe_only'::text])),
  CONSTRAINT "scope_policies_scope_type_check" CHECK (scope_type = ANY (ARRAY['group'::text, 'private'::text]))
);
-- create index "scope_policies_business_key" to table: "scope_policies"
CREATE UNIQUE INDEX "scope_policies_business_key" ON "scope_policies" ("bot_id", "scope_type", "scope_id");
-- create "system_settings" table
CREATE TABLE "system_settings" (
  "id" smallint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "payload" jsonb NOT NULL,
  "version" bigint NOT NULL DEFAULT 1,
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "updated_by" text NOT NULL DEFAULT '',
  PRIMARY KEY ("id"),
  CONSTRAINT "system_settings_id_check" CHECK (id = 1),
  CONSTRAINT "system_settings_version_check" CHECK (version > 0)
);
